INSERT INTO questions (user_id, question, answer, is_replied, is_faq, status, category, submitted_at, replied_at) VALUES
(1, 'چگونه می‌توانم در سیستم ثبت نام کنم؟', 'برای ثبت نام در سیستم، روی دکمه "ثبت نام" در صفحه اصلی کلیک کنید و فرم مربوطه را پر کنید. پس از تکمیل فرم، ایمیل تایید برای شما ارسال خواهد شد.', 1, 1, 'replied', 'registration', NOW(), NOW()),
(1, 'آیا امکان تغییر رمز عبور وجود دارد؟', 'بله، شما می‌توانید از طریق بخش "پروفایل" و سپس "تغییر رمز عبور" رمز عبور خود را تغییر دهید.', 1, 1, 'replied', 'account', NOW(), NOW()),
(1, 'چگونه می‌توانم فایل‌های خود را آپلود کنم؟', 'برای آپلود فایل، به بخش "مرکز اسناد" بروید و روی دکمه "آپلود فایل جدید" کلیک کنید. سپس فایل مورد نظر خود را انتخاب کنید.', 1, 1, 'replied', 'documents', NOW(), NOW()),
(1, 'آیا سیستم از زبان فارسی پشتیبانی می‌کند؟', 'بله، سیستم کاملاً از زبان فارسی پشتیبانی می‌کند و تمام بخش‌ها به زبان فارسی طراحی شده‌اند.', 1, 1, 'replied', 'general', NOW(), NOW()),
(1, 'چگونه می‌توانم با پشتیبانی تماس بگیرم؟', 'شما می‌توانید از طریق فرم "تماس با ما" یا ایمیل پشتیبانی با تیم پشتیبانی تماس بگیرید.', 1, 1, 'replied', 'support', NOW(), NOW()),
(1, 'آیا امکان بازیابی رمز عبور فراموش شده وجود دارد؟', 'بله، در صفحه ورود گزینه "فراموشی رمز عبور" وجود دارد که از طریق آن می‌توانید رمز عبور خود را بازیابی کنید.', 1, 1, 'replied', 'account', NOW(), NOW()),
(1, 'چگونه می‌توانم اخبار جدید را مشاهده کنم؟', 'اخبار جدید در صفحه اصلی نمایش داده می‌شوند. همچنین می‌توانید از بخش "اخبار" برای مشاهده تمام اخبار استفاده کنید.', 1, 1, 'replied', 'news', NOW(), NOW()),
(1, 'آیا امکان دانلود فایل‌ها وجود دارد؟', 'بله، در بخش "مرکز اسناد" امکان دانلود فایل‌های موجود وجود دارد.', 1, 1, 'replied', 'documents', NOW(), NOW()); 